/**
 * Zero-credit cold-start guide for MCP clients.
 */

export type GuideWorkflow =
  | 'quick_verify'
  | 'document_quote'
  | 'document_review'
  | 'source_trace'
  | 'numeric'
  | 'choose';

export function resolveGuideWorkflow(raw: unknown): GuideWorkflow {
  if (
    raw === 'quick_verify' ||
    raw === 'document_quote' ||
    raw === 'document_review' ||
    raw === 'source_trace' ||
    raw === 'numeric' ||
    raw === 'choose'
  ) {
    return raw;
  }
  return 'choose';
}

export function renderWebciteGuide(input: {
  workflow?: unknown;
  question?: unknown;
}): string {
  const workflow = resolveGuideWorkflow(input.workflow);
  const question =
    typeof input.question === 'string' && input.question.trim()
      ? input.question.trim()
      : undefined;

  const header = [
    '# Webcite guide',
    '',
    'Free plan: **100 credits/month**. This tool costs **0 credits**.',
    'When metadata.retrieval_attempts is returned, preserve its search scope and evidence limitation. An unresolved supplied source or a bounded search with insufficient evidence does not prove that the data does not exist. Official-only restrictions apply to the final publisher after redirects. For numerical claims, match metric, observation period, currency and scale; publication year alone is not the observation period. Keep conflicting official publications distinct until their scope and precision are reconciled.',
    'Retain literal source context without treating proximity or relevance as proof of a metric, observation period or unit. HTML table units can retain standard ISO currency codes, literal currency symbols and explicit nonfinancial Unit: or Units: declarations. Unknown or ambiguous headers, units and periods stay unknown; do not infer a currency from an ambiguous symbol.',
    'Local and hosted MCP expose public API tools by default. Set `WEBCITE_MCP_PROFILE=core|docs|research|full` to change local discovery.',
    'Keep the public thread_id stable when continuing work with the same authenticated owner. Internal agent checkpoints bind the owner and thread together; sharing a thread_id across accounts does not share agent history. Older unscoped agent checkpoints are not resumed because their owner cannot be established. This does not change saved review IDs, claims or completed receipts. In-memory agent checkpoints do not survive a process restart; use saved job and review receipts to recover completed work. Without MongoDB checkpoint configuration, agents use memory storage. Configured MongoDB connection or checkpoint setup failure prevents new agent startup instead of switching to memory; restoring MongoDB does not move existing in-memory checkpoints into durable storage. If a resumed agent task reports a token-usage storage or identity error, preserve the original thread and inspect saved operation receipts before retrying paid work.',
    'For new agent conversations, configure your local SDK or self-hosted MCP server with WEBCITE_API_URL=https://api.webcite.co/durable to use MongoDB agent checkpoints. Keep the same API base, authenticated owner and thread_id for every continuation. Existing conversations keep their original base; changing the base does not move their in-memory checkpoints. Saved review and job records are already durable, separately from these agent checkpoints. The public hosted MCP keeps its existing API base; /durable is an API base, not a hosted MCP connection URL.',
    'Standalone document searches and mappings require active, undeleted assets owned by the authenticated account. Asset IDs supplied by a model are checked before document retrieval. The ownership check also applies to cached document responses. A missing, inactive or foreign asset fails the ownership check; do not treat that failure as evidence that its document has no relevant content.',
    'Accounting preserves known saved conversion values. Ambiguous legacy zero defaults do not prove free usage. A conversion error does not invalidate saved verification evidence or establish a zero charge. Inspect retained operation receipts before retrying paid work. Previously overwritten conversion values are not restored by this protection.',
    'Within an established current billing period, token-usage projections serialize for the same authenticated owner. Replaying a saved citation snapshot does not deduct its token total again; additional saved usage applies only its increment. Known per-citation token-balance adjustments are preserved, and a null token balance stays unknown. Historical, duplicate, unattributed or boundary-ambiguous usage refuses projection rather than guessing. This protection does not change operation-ledger credit receipts or make external usage-meter delivery durable.',
    'Provider recording failures require reconciliation before repeating paid verification. They do not establish source-provider unavailability or a lack of evidence. Keep the saved review ID and operation receipts; previously saved results remain available. If an attempt cannot be recorded, its provider call does not start. Already dispatched work cannot be undone. Completed cache hits create no new provider attempts. Attempt status does not establish billed provider cost; missing historical attempts do not prove that no provider ran.',
    'When verification observes cancellation before a new tracked provider invocation, it preserves the original reason and does not start that invocation. Work already dispatched may still finish; a recorded attempt may have an unknown outcome and require reconciliation. Cancellation does not establish a zero charge or a refund.',
    'Cancelling a get_document_review MCP request forwards cancellation to its saved-read HTTP request. Known request credit receipts are retained when JSON parsing fails or a verification stream is missing or incomplete. Missing receipt fields remain unknown. These failures do not confirm a result, a zero charge or a refund; inspect retained operation receipts before repeating paid work.',
    'A source search cancelled before it starts preserves the original cancellation or deadline reason and does not start that search work. This does not establish that a publisher lacks relevant evidence, undo completed work or confirm a refund; inspect retained receipts before retrying uncertain paid work.',
    ...(question ? [`Your question: ${question}`] : []),
    '',
    '',
  ]
    .join('\n');

  if (workflow === 'quick_verify') {
    return (
      header +
      [
        '## Workflow: quick_verify',
        '1. Call `verify_claim` with:',
        '```json',
        JSON.stringify(
          {
            claim: question ?? 'The Eiffel Tower is 330 meters tall',
            include_stance: true,
            include_verdict: true,
          },
          null,
          2,
        ),
        '```',
        '2. Optional: `get_source_preview` on a citation URL/quote to show bind-back.',
        'Cancelling a verify_claim_stream MCP request forwards cancellation to its backend HTTP request. A stopped or failed stream requests cancellation of its unfinished response body. Partial events do not confirm a result without a done marker. Cancellation does not establish completion, rollback or a credit refund; inspect saved operation receipts before retrying uncertain paid work.',
        'Credits: typically 2–4 for verify_claim.',
      ].join('\n')
    );
  }

  if (workflow === 'document_quote') {
    return (
      header +
      [
        '## Workflow: document_quote',
        '1. Use the existing Webcite asset_id when available. For a Claude chat attachment or a file above the hosted tool limit, upload the original binary in Webcite Playground or through authenticated HTTP multipart/resumable upload within the parser\'s format and size limits. Use the returned asset_id. If the upload returns parse_job_id, wait for parsing; if it returns parse_required, call parse_endpoint. The remote MCP server cannot read a local path or automatically access a chat attachment. Use `upload_file` only for small files when the client directly supplies original bytes as base64; never reconstruct bytes from extracted text.',
        '2. `extract_document` on the uploaded asset',
        '3. `get_source_preview` with the quote and asset_id / versioned ids. This tool returns the stored unit and its bind-back only. The exact sub-unit target is returned only by the private authenticated product source preview, which opts in with a quote or a stored selector (cells or image; a tokens selector requires the same cited quote). The target kind is text (span offsets and the excerpt sliced from the source), cells (sheet A1 ranges and whole rows), region (stored image or OCR boxes) or unmatched with a reason (not_found, non_contiguous, unit_unreadable, normalization_unmappable, selector_unverified, selector_outside_unit, no_stored_cells, target_unavailable). Several matches are all returned as ambiguous, never one picked, with truncated set when more existed than are listed. Cells that cannot all be confirmed against stored cell units are reported as unverified, not matched. On a PDF page unit a text target carries frame (PDF points, top-left of the displayed page, with its rotation) only when the page was read and has a text layer, and, per match, boxes (one or more [x0, y0, x1, y1] per text line) only when the span aligns exactly and uniquely to the page text layer; otherwise that match has no boxes, and boxes_unavailable gives the reason when no match has boxes (encrypted, unreadable_pdf, too_large, timeout, busy, page_unavailable, no_text_layer, not_aligned, original_unavailable); busy means retry later.',
        '4. Optional: `verify_batch` for many quotes',
        '',
        'Do **not** invent URLs.',
      ].join('\n')
    );
  }

  if (workflow === 'document_review') {
    return (
      header +
      [
        '## Workflow: document_review',
        'Canonical binary upload reuses one structured OCR pass for raster content and preserves partial reads and errors. Native PDF coordinates preserve table year/value bindings; unreadable raster regions remain partial. PPTX native rendering retains the slide inventory, including unreadable slides. Native-only source reads do not establish complete raster coverage. Ordinary text OCR does not provide bounding boxes or certification; inspect the original for exact visual placement and unresolved content.',
        'Extraction preserves retained source units\' partial, unreadable and error states and their OCR method across PDF and PowerPoint, including image-only slides. A mixed full-scope review includes narrative assertions and scope qualifications as well as numbers; numerical extraction alone does not complete it. Bind HTML table numbers to exact original cells and headers, including uniquely matched footer years. Do not flatten table cells into prose or guess ambiguous years; leave unresolved bindings as source gaps. Partial or unknown coverage remains explicit and does not certify the source.',
        'For a numbered heading with ordered actions, keep the complete literal action sequence and its exact numbered source passage. Identical action wording at separate numbered locations is distinct evidence; do not merge it by text alone.',
        'Split independently checkable facts using ordered literal source_fragments and the complete source passage. Keep shared conditions, qualifications and negation on each applicable claim. A composed source_quote can be anchored back to one uniquely matching literal source unit; the claim must still pass wording and scope checks. Ambiguous anchors or invented wording remain rejected.',
        'A uniquely grounded literal title topic may guide document-review searches and publisher passage selection without changing the assessed assertion. Ambiguous, conflicting or unsupported topics are not inherited from model-written context. Retrieval context remains separate from factual verification: it does not resolve a source gap, certify a partial reading or revise an existing paid result. Passage selection remains bounded by the reader and cannot establish that omitted evidence is absent.',
        'Supplied URLs and discovered publisher pages share bounded semantic passage selection. Relevant evidence may use different wording from the claim. Selection preserves the quoted passage and its page or adjacent context; it does not itself establish support. Unread content, omitted candidates and pages beyond the read or selection budget remain explicit for each source. A failed or timed-out selection, or a PDF with no readable text, leaves that source unread rather than checked without relevant evidence: a discovered page keeps its discovery snippet, marked extraction_failed with no fetched evidence, and a supplied URL is rejected and yields no citation. Results from other sources are kept; a provider recording failure or a cancellation still stops the whole request. A selection that failed before the provider responded can be retried; a retained response that could not be resolved is never regenerated and stays unresolved.',
        'Structural topic headings and connectors between retained literal clauses do not become extra claims; omitted qualifications remain coverage gaps. Source evidence and successful judgments retain their server-verified identity across response projection and cache replay for the exact claim. A copied or changed receipt cannot supply that identity.',
        'Document-review result rows and claim-verification-result events may include source_assessment (version: 1). Its claim is the assessed assertion; the outer claim and claim_id retain the original report description and identity. judgment_claim preserves the exact stance identity with separately marked interpretation context, which adds no claims. basis is original_claim or source_table; optional source_asset_id and source_quote_hash reference retained source evidence; a hash alone does not establish claim truth. Missing metadata on older saved rows is unknown, never proof of a factual projection or a reason to rerun settled work. A policy-only revision reuses the saved assessment identity; changing its predicate requires fresh analysis.',
        'Literal Unicode table labels remain anchored to the original source cells and headers; recognizing a label does not translate it or supply missing metric, year, value or unit proof. Numeric-only labels and unresolved bindings remain unknown. A short source label alone does not establish that external retrieval found readable evidence for its assessed assertion.',
        'Compact saved-review pages retain optional source_assessment_summary separately from the original report claim. Normal assessed assertions and their basis remain available; claim_truncated and judgment_claim_truncated explicitly mark shortened text. A summary is not the exact saved stance identity and must not supply a new judgment or cache attestation. The full source_assessment remains saved; absent legacy metadata stays unknown.',
        'Input source coverage describes the uploaded report, separately from publisher reader coverage on its citations. A verified claim or complete input review does not establish a complete publisher read. Saved review text and compact citation_reader_coverage qualifiers preserve explicit partial reads; missing, legacy or unrecognized publisher coverage stays unknown. citation_index is the one-based position in the saved citation list. Limitation details are bounded, with omitted counts and text truncation marked; full saved evidence remains available. These qualifiers do not change verdicts, confidence or source_assessment identity. Verification stream cancellation still leaves incomplete results and credit outcomes unconfirmed; inspect retained receipts before retrying.',
        'When parsing omits list numbers, literal inline heading boundaries still distinguish headings from their factual body. Structural choice headings are not facts; procedural requirements, action ordering and shared conditions remain part of the review.',
        'Extraction retries identify the same grounded assertion when its literal source quote changes from heading plus body to body alone, preserving the first stored claim instead of appending a second claim to check. Separate source occurrences, assets and page identities remain distinct. Verification runs at most three funded claim tasks at once, bounded by available credits and the remaining consecutive-failure budget; completed results remain saved if another task fails.',
        '1. If the file is already in Webcite, use its asset_id. Hosted MCP uses stateless authenticated POST requests; missing or obsolete mcp-session-id headers do not block tools. Backend job_id and review_id preserve workflow progress across reconnects. No balance preflight is required: use inline credit_usage from normal responses, and get_credit_balance only for an explicit balance question or unresolved credit refusal. Missing receipt fields remain unknown. For a Claude chat attachment or a file above the hosted tool limit, upload the original binary in Webcite Playground or through authenticated HTTP multipart/resumable upload within the parser\'s format and size limits. Use the returned asset_id; the remote MCP server cannot read a local path or automatically access the attachment. If completion returns parse_job_id, wait for parsing; if it returns parse_required, call parse_endpoint. Use `upload_file` only when the client directly supplies original bytes for a small file, never reconstructed document text. Save the asset_id and source_version_id from upload. For a full review, proceed directly to review_document: the server reads the stored representation and waits for parsing when needed. Do not pay for extract_document merely as a review prerequisite. Use extract_document only when the user also needs extracted content or a specific source-read anomaly requires inspection; its per-call charge can apply even when stored OCR is reused. Never call a partial read complete.',
        'Optional source inspection: some connectors show only MCP text and omit structuredContent. Extraction text is bounded at 16,000 characters and lists links beyond that limit. An asset_id is not a source_version_id. Use get_latest_representation and read_source_unit for complete stored units when needed; extract_pages costs 1 credit per call. Repeating `extract_document` or `extract_figures` incurs the stated per-call credits. These are anomaly/content inspection tools, not mandatory review preflights.',
        'For a JPEG/PNG whose retained text lacks layout evidence, explicitly opt in with extract_document visual_rendition:true, the owned asset_id, exact source_version_id and an explicit idempotency_key. This operation costs 1 account credit; preserve its key and receipts on failure, never automatically start another paid attempt. It returns a separate model-generated partial representation without changing the selected review source. Use the returned source_units IDs with read_source_unit to inspect its stored visual evidence, then inspect the exact saved gap with get_review_source_span, whose role may remain unknown. An explicit record_review_nonclaim action can reference visual_evidence representation_id and unit_key; the server rechecks source bytes, literal offsets and geometry. Whole-label bold or italic formatting can match the same plain-text label while preserving its wording. Layout roles do not prove nonclaim, agent actions do not imply analyst approval, and factual/numeric headings remain gaps. Only an isolated source-bound page footer can support a numeric nonclaim. Eligible inactive failed residual reviews reconcile complete retained extraction responses without new generation or rewriting saved claims; missing, incomplete or ambiguous evidence refuses. Partial source reads stay partial even when these gaps are accounted for.',
        '2. Call `review_document` with a clear prompt, asset_ids and a stable thread_id. Pass official PDF URLs supplied by the user or found with `search_sources` in source_urls, with the required source filters. Save its job_id. There is no fixed claim count. The server checks claims in the background and saves each completed result. When an account-credit spending limit is required, pass max_account_credits as a positive integer. It caps new charges plus outstanding holds for that execution; historical completed claims are not charged again. The cap is immutable for the same job/idempotency key, including omission after a capped submission. A later explicit retry execution has its own budget: pass its authorized cap explicitly. Omission requests no execution cap. This does not bound provider calls or provider currency cost, and it does not guarantee full coverage. If the response fails to confirm the requested cap, enforcement is unknown: inspect the existing job and do not resubmit automatically.',
        '3. Inspect the saved claim list and source coverage for every material figure, period, comparison and relationship in all readable pages/sheets. Do not infer full source coverage when coverage_complete or source_read_complete is missing or false. `extract_figures` can add recognized financial metrics, but zero results does not mean there are no numbers. Check omitted claims individually with `verify_claim` using distinct stable idempotency keys. Report an official PDF read failure instead of substituting secondary sources. Evidence must address the same metric, period, unit and geography.',
        '4. Poll `get_document_review_job` with job_id at zero credits, waiting about 30 seconds between checks. A review_id can appear before work finishes. Unless the user requests interim results, wait for a terminal job status before reading result pages, then call `get_document_review` to read saved checked and pending claims, source coverage, uncovered spans, rejected candidates and explicit nonclaim dispositions. Copy the returned next_page_input exactly for each next call, including exhausted-stream offsets, until it is null. Do not reset exhausted offsets to zero. The individual next_offset, next_gap_offset, next_rejected_offset and next_disposition_offset remain available. For a source-attested heading, table title or navigation gap, read its exact text with `get_review_source_span`; record a nonclaim with `record_review_nonclaim` only after assessing the entire passage and giving a rationale that it contains no factual assertion. Structural role alone never closes a gap. Leave any assertion-bearing passage uncovered. For the final report, use the saved claim outcomes, verdict summaries and citation URLs on these pages. A compact view can omit detailed evidence; omission from the view does not mean it was never saved. Compact fields omitted are unknown, not absent. Report known material_claims (physical rows excluding duplicates), total_claims (all physical rows), duplicate_claims and non_factual_claims separately. Material counts can include non-factual rows and do not imply all rows are factual assertions. A duplicate display alias can have a different id; original_claim_id is its stored original identity and duplicate_of_id identifies the canonical assertion. Display aliases do not change stored IDs, citations or paid operations. Report pending, failed, rejected and uncovered counts separately. pending_claims is unfinished work and includes failed_claims; failed is a subset, never add it again to a total. Counts do not establish attempt history; do not call other unfinished rows never attempted without recorded attempt data. A provider access error does not rule out incomplete extraction or source coverage. Null or missing counts are unknown, never zero. Do not group unknown rejected or uncovered counts with known zero pending or failed counts. A completed job means processing finished; it does not prove complete source coverage. For a queued or running review, obey poll_after_ms with waits of at most 30 seconds. Never multiply remaining claims by per-claim latency into a long blind sleep. Stop polling immediately on a terminal status and report failed or interrupted work. Do not infer source weighting, prioritization or analysis absence from omissions. Fetch verbose evidence details only when that specific audit requires them, not routinely. A null summary is unknown and a summary_truncated flag means the complete saved summary was not displayed. Use source titles as link labels and complete returned URLs as link targets; never replace URL paths with ellipses. Extra citation/source-unit endpoints are needed only for requested evidence details or a specific anomaly. Inspect those citations with `get_source_preview`; `verify_batch` checks quote binding, not claim truth.',
        '5. If credits run out or the job fails, give the user the saved checked claims, unchecked claims, and uncovered source passages now. After credits are available or the failure is diagnosed, call `review_document` with the same prompt, thread_id, assets, source URLs, filters and billing flags plus retry_failed: true and the returned retry_idempotency_key. Keep the original thread and file. The failed job receipt is retained; completed claims replay without a new charge. A failed or interrupted execution releases only its own inner review lease for prompt explicit retry, preserves saved outputs, and leaves foreign, newer or terminal leases unchanged. Completed extraction responses are also reused when the source, extraction request and model settings are unchanged. A failed or incomplete extraction response is not reused as a successful result. Do not repeat separate `verify_claim` calls that already completed.',
        '6. To apply the current evidence policy to a settled claim, read its original_result_hash and call `revise_document_claim_analysis` after the review stops. This reuses saved snippets without new research, model calls or credits. The original result and receipt remain in revision history. A missing scope assessment stays inconclusive; this operation does not promise fresh semantic analysis.',
        'Saved-review continuation covers claims, uncovered passages, rejected candidates and nonclaim dispositions separately. The SDK rejects a returned cursor that repeats, skips or contradicts its saved page boundary instead of inventing a replacement. Copy a valid next_page_input exactly, including exhausted streams. An absent cursor while stream totals are pending or unknown does not establish exhaustion or complete coverage. A pagination contract error is not a reason to start another chargeable review; inspect the retained page and API response.',
        'Credits: optional extraction costs 1; document review charges per claim. Upload responses retain available credit_usage in both text and structured output; a missing upload receipt means unknown charge, never zero. credit_usage describes this HTTP request; review_usage describes accumulated operation-ledger charges, not polling costs. Account usage lists and totals no longer repeat the sub-prompt rows of a multi-prompt verification once its combined record is saved; legacy grounded sub-prompt records and usage recorded before this change can still appear twice. This does not change credit charges or billing. Multi-prompt verifications saved after the stance-usage fix also record the tokens spent on per-claim stance analysis in their combined usage record; records saved before that fix omit them. If stance usage for any claim cannot be measured, the response reports usage_unknown: true rather than a partial total. Token totals and the legacy token balance fields (consumed, current_balance) therefore rise for these requests; credit charges per request are unchanged. Verifications saved after the verdict-usage fix also record the tokens spent generating verdict explanations, for single-prompt and multi-prompt verifications, and count them in token totals and the legacy balance fields; records saved before that fix omit them. An unmeasured verdict call on a multi-prompt verification reports usage_unknown: true; a single-prompt response has no usage field. Credit charges per request are unchanged. Balance and saved-review readback cost 0.',
      ].join('\n')
    );
  }

  if (workflow === 'source_trace') {
    return (
      header +
      [
        '## Workflow: source_trace',
        '1. Call `extract_document` on the uploaded screenshot or slide. Read the actual table labels, units, years and distinctive figures. If extraction is incomplete, say which part is unreadable.',
        '2. Call `search_sources` with those exact details. If results are secondary or empty, refine the search using a likely regulator or report title suggested by the table. Do not treat a domain filter returning zero as proof that the official source does not exist.',
        '3. Open candidate URLs with `get_source_preview`. Identify the original publisher and page only when the same metric, period, unit, geography and table values are present. For a claim check, pass confirmed official PDFs to `verify_claim` in `source_urls`.',
        '4. If the original source or country is not established by the document and checked URLs, report it as unresolved. Do not infer a country from currency alone or cite a news summary as the original publication.',
        '`ask_document` checks numerical answers inside supplied text; it does not discover external source URLs.',
      ].join('\n')
    );
  }

  if (workflow === 'numeric') {
    return (
      header +
      [
        '## Workflow: numeric',
        'For a selected original spreadsheet cell, retain its sheet and address, literal display and number format, and nearby labels. A source-only cell reading is not an approved Figure or a recalculated formula result.',
        'Retain formula presence and available formula text or metadata even for self-closing formula nodes or shared-formula followers with no local text. An absent or whitespace-only cached value is absent; a literal cached zero is present. A cached formula value marked present_unverified remains unresolved. Spreadsheet parsing and native source construction do not verify or recalculate formulas and are not calculation authority.',
        'Use scope.period only for the exact source-supported period. Preserve an analyst literal opaque or partial label, such as an eight-month period, without reconstructing annual boundaries. effectiveTime: null means the effective interval is unknown; it does not establish a full year. Period, actual versus forecast basis and comparable metric meaning still require original source evidence before review.',
        'In the dedicated DD host workflow, signed selected model and Figure inputs retain evidence.entityId, rawLexeme, displayLexeme, numberFormat, scopeEvidence and effectiveTime from the selected occurrence and reviewed interpretation. The input manifest binds this evidence; the existing assertion identity is unchanged. Preserve the literal raw reading separately from valueDecimal and carry unknown intervals as null. These inputs are not public MCP tools and do not approve a report Figure or verify a formula cache.',
        'If a selected input contains semanticScope.measurement or signed evidence.measurement, preserve each optional fact and its exact source clue: retention horizonMonths, cohort and ratioMeaning; workforce basis and geography; ACV basis, cohort and contractId; and costConvention. Supplemental facts require proof from the retained selected source; they may fill missing facts without changing assertion identity, review identity or semantic role. Conflicting explicit and supplemental facts must fail visibly, never overwrite the reviewed meaning. Omission means unknown and preserves the existing reading. A cost formulaWitness establishes only the source expense convention from its retained P&L labels and formulas, never the correctness of cached results. These source facts require no new DD screen, review workflow or generation gate; support for the optional fields alone does not prove automatic extraction supplies them.',
        'For a validated registered NRR conversion, retain the signed source value and unit separately from the DD target value and unit. Source ratio 1.18 displayed 118% maps to target 118 percent without rewriting source identity. A source multiple requires explicit NRR ratio meaning; an unrelated valuation multiple is not convertible. Existing answers and citations must use the target unit for presentation and the exact retained source lexeme for citation validation. Unknown retention horizon or cohort remains unknown after conversion.',
        'Compare only the same metric meaning, entity, measurement scope, period, interval, actual or forecast basis, role, unit and currency. A shared numeric unit or generic definition does not make Net New ARR and Ending ARR, FTE and total headcount, contract and blended ACV, or Gross Margin and retention comparable. Missing retention horizon, cohort, workforce basis, contract scope or cost convention needs evidence; do not infer it from a default or a signed number. Ratio, percent and multiple representations need an explicit metric-specific conversion contract; do not coerce unrelated multiples or negate expenses automatically. A fiscal-year label maps to an interval only through a source-stated or configured fiscal calendar; without one it stays unresolved and is never treated as the calendar year. For find_contradictions, state the meaning of each claim in claims[].period_kind: flow is a total over the interval, stock is a level at a date, and omitted means unknown. Differing values for the same metric, entity and exact period contradict. Nested or overlapping stocks with differing values also contradict. A year-to-date or other partial-period flow and the annual flow are distinct periods, not a contradiction. A stated stock and a stated flow are distinct and never compared, such as an as-of balance against a total over an interval. When either kind is unknown, nested or overlapping periods fail closed as contradiction_scan_incomplete: insufficient_comparison_context instead of a contradiction, and the refusal still lists the pairs already found. Values retained before this meaning was recorded read as unknown.',
        'For automatic extraction in an existing DD analysis, consume only results bound to the current selected source, receipt, source units, engine and metric configuration. This private backend handoff is separate from analyst-approved mappings and adds no public MCP tool or DD review prerequisite. Preserve source raw and display readings, source-supported canonical meanings, exact clues, extraction method, uncertainty, physical and semantic coverage, and operation usage. A present formula cache may be an unverified source reading requiring review; an absent cache is unknown, never zero. Extraction confidence does not verify arithmetic or establish analyst approval.',
        'Fresh paid automatic extraction in the private DD handoff bills the authenticated API service principal authorized by the exact active product grant and signed Analyze request. Source tenant, actor and custody remain isolated from the payer. The existing document tariff and operation key apply once per document/model/prompt/media identity, not per page or batch; the immutable authorization and credit root bind that request, with unknown token and time budgets left unset. Settlement and refunds use the actual subscription that funded the operation. Cached attributed dispatch revalidates the active grant, principal and original payer without a second hold or provider call. Completed retained-ledger reads remain read-only and do not require a new billing hold. Failed authorization or insufficient credit must remain an explicit failure, never an empty successful extraction.',
        'Automatic model reads bind the actual provider endpoint to cache and operation identity. Gemini global routing uses aiplatform.googleapis.com; explicit regional routing keeps its regional endpoint. A corrected endpoint is a distinct provider request and must not overwrite a retained failed or unknown outcome. Preserve completed extraction ledgers and original source receipts. Provider failures retain only safe status or failure codes alongside their original operation; missing response, token or cost metadata stays unknown. Reading a failed cached outcome must not silently redispatch it or present extraction as successful. Structured source reads use supported model-specific thinking and output settings that allow a complete response. MAX_TOKENS or other incomplete output remains a retained failure, never salvaged into successful extraction. Spreadsheet label mapping returns exact configured matches only; unmatched original readings retain their source values and uncertainty in the ledger.',
        'Automatic spreadsheet readings retain source-supported comparison scope: explicit Entity, Company or Issuer labels can identify the subject; explicit total, subtotal, standalone or component wording can identify its semantic role. Contradictory or unmarked scope stays unknown and never implies analyst approval. Exact request-configured metric aliases carry their configured unit when the native reader has no competing unit. Calendar quarters retain their bounded calendar interval; fiscal quarters retain fiscal identity without inventing an interval from an unspecified fiscal calendar. Consumers must preserve scope differences and unknowns when comparing readings.',
        'Current automatic source extraction uses selected-source-automatic/7. Numeric values must not replace source row labels or period headers. Recognized whole financial year or quarter labels preserve printed A/ACT actual and E/EST/F/FCST/P/PLAN/BUDGET forecast qualifiers with their exact source clue. Bare years and suffixes in non-period labels do not establish basis; conflicting qualifiers remain unknown, and fiscal labels do not establish a calendar interval. Exact configured metric names are recognized without broadening them into component or derived measures; an explicitly empty alias list still disables deterministic name and alias matching. Magnitude suffixes must be complete numeric suffixes, never prefixes of words such as months or units. Numeric substrings embedded in identifiers such as B2B or version labels do not establish standalone source numbers; retain real standalone quantities and the original source text. Native prose parentheses do not by themselves prove an accounting-negative sign; ambiguous signs remain unresolved with their exact raw source. Spreadsheet accounting conventions retain their existing interpretation. Model reading identities include their complete retained source binding and proposal context. Distinct quotes or source contexts remain separate even when metric and value agree; identical repeated proposals within the same retained source unit are deduplicated before classification and coverage counts. Historical consumer projections may coalesce exactly identical retained reading IDs without rewriting their immutable ledger; differing evidence under the same reading ID must be rejected. Native metric association uses the local value clause; an adjacent value and label across a source separator cannot supply its metric. Metric association checks the retained native context independently of a proposed quote; a shortened quote cannot hide a conflicting source label. A model proposal that contradicts an explicit source metric alias remains an unavailable reading with its source and reason; it must not become a different metric or discard valid sibling readings. Provider and source-custody failures remain failures. The extraction revision changes immutable ledger identity while existing native receipts and representations are reused. Identical model inputs retain their existing versioned provider identity and cached response; changing the reading rules alone does not authorize another paid call. A retained selected-source-automatic/1, selected-source-automatic/2, selected-source-automatic/3, selected-source-automatic/4, selected-source-automatic/5 or selected-source-automatic/6 result is readable only through an explicit automaticExtractionRead.manifestHash matching that immutable historical result; current reads and fresh execution never silently substitute it. Historical results retain their original engine, findings and uncertainty, without being relabelled as corrected output.',
        'Existing authenticated product context queries can include automaticExtractionContext with the exact declarative metrics, metricConfigHash and optional companyHint used by Analyze. The query signature binds that configuration. Current selected-source receipts select only the corresponding immutable retained extraction ledger; a context read never invokes a provider, reconstructs extraction or chooses an arbitrary latest configuration. The additive automaticSourceLedger returns full analyze envelopes with source, configuration, engine, manifest, readings, observations, coverage and original operation attribution. Missing exact ledgers produce source-specific unavailable gaps; omitted configuration is explicitly not_requested. Corrupted ledger or changed source custody fails visibly. Returned manifests and gaps bind the context query identity alongside existing source references and memory notes. Graph-operator refusal is independent of ledger availability: retained source readings may still be retrieved with their original uncertainty, never relabelled as resolved graph assertions. When sources were analysed with different configurations, send automaticExtractionSelections instead: one entry per source with its exact Analyze request and the retained manifestHash to read. It cannot be combined with automaticExtractionContext, requires explicit sourceVersionIds, and every selection must name a queried source whose current selected receipt matches. A pinned manifest is never replaced by a newer or different one; a changed receipt or manifest is a conflict, a missing retained ledger is a source-specific gap, and a queried source without a selection is not_requested. An empty automaticExtractionSelections list means no selection, the same as omitting it. A memoryOnly query with selections checks only the selected sources. Product source limits apply to memoryOnly reads that request ledgers.',
        'Existing private product Analyze can retain paired source findings with sourceFindings: the exact case, context path and sorted selected corpus (source version, analysis receipt and original bytes hash), plus its corpusHash. The Analyze version is the first sorted source. Its signed sourceFindingsHash binds the request; an optional sourceFindingsRead object and separately signed sourceFindingsReadHash select a retained current result or exact historical manifest without execution. This branch is exclusive with native analysis, automatic extraction and attempt fields. It adds no DD frontend, analyst review prerequisite or generation workflow.',
        'For shared product memory, context/query can include sourceFindingsContext with that complete request and optional read intent. This is always a retained read. Every corpus member is independently authorized for the case and checked against its selected source receipt and representation, even when graph retrieval selects a smaller subset. sourceFindingsMemory distinguishes not_requested, available, partial, unavailable and indeterminate with explicit gaps; graph refusal does not erase available source memory. Reads never call models, parse originals or reserve credits, and a missing exact result never becomes an empty successful analysis. A read-current request on a deployment without findings provider configuration returns indeterminate with reason source_findings_provider_unconfigured: the retained result may exist but cannot be located, so treat it as unknown, not missing; pin read.manifestHash to read an exact retained result without provider configuration. Preserve the immutable manifest, engine, corpus, actual review identity, stage receipts, coverage and limitations across chat, analysis, memo, checklist, research, screening and portfolio consumers. To receive one canonical evidence list, add evidence {include, maxItems?, maxChars?} with an explicit contextPath; include names passages, readings, findings, notes and source_diagnostics. The evidence policy is part of the signed query body. The response adds composedEvidence (version product-query-evidence/1) built only from the graph refs, ledgers, findings and notes the same request already read: no provider, model or extraction call. Each item keeps its origin (source_statement, automatic_interpretation, source_reconciliation, user_assertion or source_diagnostic), a stable id derived from upstream identity and source occurrence, and the original locator, value, quote binding and uncertainty. Graph snippets stay physical_source_only; on a meeting-scoped query each passage carries the same contextScope (meeting or company) and order as the top-level refs, as payload outside its id. Notes stay unverified user assertions and never corroborate a source. Unavailable values appear only as diagnostics. A finding is offered with all its witnesses or omitted whole (max_items or incomplete_witness_group). Equal values from different sources stay separate; one id with two different payloads is a 409 integrity error. Defaults are 100 items and 12000 characters, maxima 2000 and 200000. maxChars counts only rendered text in UTF-16 units: passage snippet, note text, reading metric, value, unit, raw lexeme and display, finding question, description, claims and witness quotes, and diagnostic reason, lexeme and display. Admission follows priority order and stops at the first item over maxChars. Separately the serialized envelope stays within 200000 UTF-8 bytes, and coverage metadata alone over that bound is a 413 product_evidence_metadata_limit; omissions are counted per origin, source and reason. composedEvidence.receipt is null in this version: composed-evidence receipts are not yet retained or exposed, so do not wait for or request one. coverage reports inventory (only sources this request checked; a memory-only pinned read is not_checked), retrieval (gapCount is exact, gaps is a sample of at most 100), ledger, findings and note staleness separately, so a refused graph or complete inventory never implies complete extraction. coverage.notes.included counts offered notes and current counts notes read. coverage.findings.outsideQueriedSourceVersionIds counts finding witnesses from sources outside the queried selection, so a subset query is never silently a whole-case comparison. Without evidence the response is unchanged.',
        'Paired findings are evidence_only interpretations with exact original quote spans, locators, source-unit hashes and source receipts for each occurrence. Keep the derived description and reconciliation question separate from quoted original evidence. Unknown subject, metric meaning, period, population, basis, unit, currency or other necessary dimensions cannot establish a contradiction. Plausibly matching source assertions with an identifiable difference may remain reconciliation questions with explicit uncertainty; known incompatible scopes exclude the pair. A comparison response that fails its strict output contract is not accepted source memory. Preserve its raw response and failure, and never automatically redispatch it. Scope field equality alone is not proof of source meaning. Ground literal occurrences independently from proposed qualifiers: unsupported interpretations remain unknown with explicit limitations, while independently evidenced incompatible meanings still exclude a pair. A source-bound consistency question is not a corrected value or a verified discrepancy; preserve measure, currency, population, period, basis, table completeness and displayed precision when checking source-stated bounds or aggregates. Single-source formula diagnostics retain their existing path. Complete bounded review coverage does not certify exhaustive conflict discovery, formula correctness or analyst approval, and an unsuccessful risk summary must not remove retained source findings.',
        'Fresh retained-corpus review has two separately bounded existing Ask operations: grounded source-claim extraction, then paired reconciliation against the full bounded retained source corpus as well as accepted claims. Comparison input may group retained units under their original source identity while preserving every unit identity, locator and source text. The comparison request deadline and transport are bound to its provider settings. A comparison becomes source memory only after its complete provider response passes normal-stop, schema and original-source grounding checks. The owned deadline covers response headers and body; a transport failure retains an explicit unknown provider outcome without automatic redispatch. The comparison stage can propose omitted literal claims with explicit source and unit identities; they must pass original-source grounding and the same scope checks before contributing a finding. Source coverage remains partial where spans are unclassified, and a normal provider stop does not prove exhaustive discovery. Each uses the existing Ask tariff of 5 credits, with a shared maximum of 10 credits and at most two provider dispatches, without automatic repair or hidden per-source calls. The active product grant authorizes the service payer separately from source custody. Trusted execution identity includes the corpus, request, engine, actual provider/model/endpoint, both prompts and settings. Retained completed stages replay without another hold; partial coverage and failed or unknown outcomes remain explicit. A changed comparison policy may reuse a compatible accepted extraction stage only after validating its original request, source custody, input, prompt, provider settings and payer authorization. An explicit stage executionHash identifies that original execution; absent stage executionHash retains the enclosing execution identity for historical results. Keep the original operation and reply, link its usage to the consuming execution, and dispatch only the changed comparison stage. A new comparison identity must not replay an older empty finding result. A changed deterministic interpretation policy has its own immutable result identity; it may reprocess an accepted retained provider response only after revalidating the same source custody, prompt, input, provider settings and payer authorization. Preserve the original response, operation and prior manifest, link the new result to those original stage identities and do not charge or dispatch the provider again for that reprocessing. A persistence failure before provider dispatch can retain a reservation without an accepted response. After fixing the cause, resume only that exact case, source custody, provider, prompt and settings identity with the same execution key to reuse the existing reservation. Failed or unknown provider responses must not be blindly redispatched. Preserve both real stage operation IDs and aggregate usage, rather than inventing one operation receipt for both stages.',
        'Product context-graph passage queries use the same normalized whole-word vocabulary for seed matching and passage selection, including meaningful two-character terms. Graph retrieval can also scope by retained entity resolution when a caller supplies entity scope (mentions with reviewed aliases, typed relationships and source-unit anchors); this is an engine capability, and product context/query and DD queries do not supply that scope yet, so a passage missed under an alias is not evidence that the fact is absent. With that scope, a question naming a retained entity expands by the exact names and reviewed aliases of that entity, never by token similarity; relationships relevant to the question recover anchored passages in other documents within two hops; and source units resolved to a different entity, such as a lookalike sharing topic words, are excluded per unit, while numbers inside a shared unit are dropped only when their own entity clue names the other entity. Entity scope never refuses on missing related evidence: every unreachable relationship target is listed in missingSupport with a relevant flag (true when a relationship-type word shares a stem with the question or the full target name appears in it), and the caller decides how to report the gap. At most three passages are cited only because of a relationship. An invalid entity scope refuses with invalid_entity_scope and an oversized one with entity_scope_too_large. Questions naming no retained entity retrieve exactly as before. Native product Analyze also retains a deterministic per-source semantics manifest for the selected analysis receipt: defined terms and aliases with source witness spans, exact-phrase entity mentions, and explicit Exhibit, Schedule, Annex, Appendix, Section, Clause, Article and titled-agreement references, all unresolved. It also keeps the Exhibit, Schedule, Annex, Appendix, Section and agreement headings found in the source as heading targets, and labels each entity organization or defined_term. It costs no credits and makes no model call. It is not yet returned by any endpoint or used by retrieval, and spreadsheet receipts and receipts analysed before it existed have no manifest. An analyst can add, reject or restore an entity alias for one case through the signed product action POST /api/v2/integrations/product/sources/semantics/alias-decisions (delegation audience webcite-product-semantics-alias-review, request hash over the exact body, which must have no surrounding whitespace in alias or rationale): caseKind, caseId (at most 191 characters, as for context/query), sourceVersionIds, decisionId (a UUID), registerEntityId, alias, action add, reject or restore, and rationale. Sending the complete selected sourceVersionIds of the case is the responsibility of the caller: the register is computed from exactly the sources sent, each of which is authorized and must be selected, as for context/query. The case register is computed per request from the manifests of those sources and is never stored: one entity per shared normalized name or source-witnessed alias, role words such as "the Company" never join documents, and entities of different kinds (organization and defined_term) never merge. Different names stay apart unless a source witnesses a shared alias; reject that alias to split them. The register entity id is a hash of its member source entities. The delegated actor is the analyst identity. Each decision records the members of the entity it was made on (entity, source lineage, kind and normalized name) and the sources sent. A rejection is a cannot-link on that alias: it starts at those members and spreads to entities joined to them by other names, so sources added later that join either side by name can never re-join the two sides through the rejected alias, and it keeps applying when sources are added or removed. An entity linked to them only through the rejected alias is not affected. A rejection removes only that alias: to separate entities with the same name, reject the name and every shared alias. A decision also follows its members to a newer version of the same source when the normalized name is unchanged, reported as carried; it is stale only when none of its members, or their newer versions, is in the request. A restore undoes every earlier rejection of that alias that shares a member with the entity it names (a later rejection wins again). It must name an entity holding a member the rejection was decided on: on an entity the rejection reached only through other names it is refused with 409 ALIAS_RESTORE_NOT_DECIDED, and an add is allowed there. An add of an alias rejected on an entity holding a decided member is refused with 409 ALIAS_REJECTED_USE_RESTORE: send restore instead. An added alias carries the analyst identity and no source witness, attaches to whichever current entities hold its members, and never merges entities; if those members are now split across entities it appears on each with ambiguous: true. The latest add or reject for the same members and alias supersedes earlier ones. A same-content retry of a decisionId, including two concurrent identical requests, returns the retained decision; different content under that id, or the same id in another case, is a 409. A register entity that is not current is a 409; rejecting an alias the entity lacks, adding one it already has, or restoring one that is not rejected is a 400. A case admits at most 5000 decisions over its lifetime, restores included, enforced atomically (retries of one decisionId count once); a new decision past that is a 409 with code ALIAS_DECISION_LIMIT, while reads never refuse and, past the limit, apply the newest decisions and report the overlay as partial. The response returns the decision, overlay accounting (applied, carried, superseded, stale), overlayStatus and the resulting entities. Reference resolution and the case register are not yet returned by context/query or used by retrieval. Send the complete authorized selected-source scope for the requested case; legacy filename or keyword filters must not silently narrow graph evidence. DD and diligence context queries accept at most 200 selected sources and reject an oversized scope explicitly. An explicit DD source selection at its exact deal, portfolio-company or screening-prospect root can include sources bound beneath that same owner, such as sibling board meetings. Each descendant binding must pass the existing tenant, workspace, selected-version and immutable-revision checks; the complete binding snapshot is checked again before returning evidence. Other context queries keep their ancestor-only binding scope. A DD board meeting query sends caseKind portfolio_company with that company as caseId and contextPath [{kind: project, objectType: portfolio_company, id: company}, {kind: thread, objectType: board_meeting, id: meeting}]. It returns sources bound at that meeting path first, then sources bound at the company root, and adds contextScopes (bindingId, sourceVersionId, revisionId, scope meeting or company, contextPath) plus a contextScope label on every reference, with meeting references ordered first. For passage operators (select_passage, filter_passages), meeting sources are retrieved first with the full limit and company sources fill only the remaining slots, so company matches cannot crowd out meeting evidence; lookup_number, count_matches, intersect_sets and refused operators run once over all scoped sources (reported as one combined plan) so conflicting exact values still refuse and counts stay exact; scopedQueryPlans reports each pass (scope, sources, limit, status, refCount, queryPlan, or skipped when no slots remain), and the merged queryPlan.truncated is true when the company pass was skipped. Sibling meetings, other companies, the portfolio and the pipeline are never admitted; a findings request rooted at the meeting path likewise admits only that meeting and the company root. When a query with a contextPath also supplies the optional sourceFindingsContext, sourceFindingsContext.request.contextPath must equal it exactly or the query is refused with 400 before any read. Requests at the company root or any other path return no contextScopes and are unchanged. When caseKind is a DD owner (deal, portfolio_company or screening), contextPath must start at that exact signed owner project node; a path rooted at another deal, company or prospect is denied before any binding, graph or memory read. Preserve graph-selected references ahead of supplemental ledger or findings evidence instead of discarding them through a second local relevance filter. Carry queryPlan.truncated and any consumer token-budget omissions into the drafting context. Retrieved excerpts, an empty lexical match or missing coverage metadata do not establish that a fact or document is absent from the entire room. Keep original source, selected receipt, unit and locator identity with every retained reference.',
        'A product host that binds sources to a context path can send includeInactive: true in the signed source-context list body. The response then adds inactiveBindings: each unbound or deactivated binding at that exact path with its bindingId, assetId, sourceVersionId, latest revisionId and active false. Pass that revisionId as expectedRevisionId to bind the source at that path again, for example after an unbind whose revision the host failed to record. Without the flag the list is unchanged. Inactive bindings never count toward the active list limit and are capped separately at the same per-product limit; above it the inactive list is refused with 409. The same product grant, delegation signature and workspace checks apply, and a binding revision that does not match its workspace, tenant, asset or path is refused with 409.',
        'Automatic native table readings preserve explicit metric, period and named entity clues from intact table headers and rows, including an explicitly labelled entity column after an index column. A unique exact configured metric label can follow a nonmetric index column when the intact row and corresponding value header establish the relationship; competing metric labels or ambiguous combined cells remain unresolved. This uses the requested metric definitions, including custom aliases. Native table relationships retain needs_review with source_table_scope_inferred; exact literal binding does not establish layout confirmation or analyst approval. A model proposal may retain explicit column qualifiers when its complete quote uniquely matches an intact source row after table separators and cell whitespace are normalized, with one exact value cell and a matching source label. This does not broaden deterministic metric aliases or turn a model proposal into a verified reading. A quote that differs from the retained native text keeps physical-source-only attribution and no exact raw native span; ambiguous rows or cells remain unresolved, and conflicting known metric aliases still reject the proposal. An explicit as-of period in an ancestor heading applies only within its bounded section; sibling sections do not inherit it. Contract start dates and contract durations do not establish the metric observation period. Broken or ambiguous table geometry remains unresolved rather than acquiring inferred headers or entities. Comparison dimensions apply across configured metrics, including custom metrics. Preserve independently evidenced axis and member meanings for population, product, channel, geography, denominator, contract or other source dimensions, alongside entity, period, interval, basis, role, unit and currency. Keep the exact supporting caption or span separate from the qualifier value, so surrounding metric values do not become scope identity. Different axis order does not imply different scope; contradictory or unsupported dimensions remain uncertain. Special retention, workforce and ACV fields are compatibility facts, not a complete list of possible qualifiers. Do not treat arbitrary wording as an alias, discard dimensions or infer a company total from a scoped row.',
        'In a host product that offers contextual numeric review, a human reviewer may explicitly mark a selected year label, date label, ordered year-range label, identifier or rejected prose cell as source context after checking the original. Date and year-range labels must match the whole retained spreadsheet cell under its Date or Year context; a lexical fragment or inferred period is not enough. Spreadsheet prose must match the whole retained text cell at its exact sheet and address; PDF prose keeps its source span. Rejected prose may retain its original assumption-basis annotation as context only; it must have no metric, entity, unit, currency, scale, definition or semantic scope and cannot be a projected numeric assertion. A year, date or year-range label or identifier with any basis annotation remains ineligible. Signed source coverage must count contextual decisions separately from reviewed numeric assertions. This is a host decision in the dedicated DD workflow, not a public MCP tool or an approved Figure. Other unresolved values remain unresolved; unmarked source reads do not establish actual versus forecast meaning.',
        'A host may submit up to 100 selected numeric readings for one human batch decision. A spreadsheet candidate.raw can be printed display text, such as 30.2%, while sourceRawLexeme is the sealed stored cell value, such as 0.3015873015873016. The proposed expectedRawLexeme must use that stored value, never the rounded display; review the exact original cell and receipt before filing. Each reading still needs its exact original source unit (spreadsheet cell or native PDF span) and complete period, unit, basis and definition evidence; the batch publishes one selected review receipt only after every item passes. One rejected or stale item leaves the source selection unchanged. Unknown currency or meaning stays unresolved, and a reviewed reading does not by itself approve a report Figure. This host workflow is not a public MCP tool.',
        '1. `extract_document` to read every page and identify its file format. `extract_figures` only finds recognized metrics; zero metrics does not mean the page has no numbers.',
        '2. Use `analyze_document` for PDF, spreadsheet or JPEG/PNG/WebP numeric analysis. Image figures are OCR/model reads and need source review. For a whole-slide external fact-check, also use `review_document`; use `analyze_conflicts` only when you have figures to compare.',
        '```json',
        JSON.stringify(
          {
            asset_id: 'asset_...',
          },
          null,
          2,
        ),
        '```',
      ].join('\n')
    );
  }

  return (
    header +
    [
      '## Choose a workflow',
      '- `quick_verify` — fact-check a sentence (most common cold start)',
      '- `document_quote` — bind a quote inside an uploaded document',
      '- `document_review` — check every material claim in an uploaded document',
      '- `source_trace` — find and check the original publication behind a screenshot or slide',
      '- `numeric` — figures and conflict analysis',
      '',
      'Re-call `webcite_guide` with `{ "workflow": "quick_verify" }` (or document_quote / document_review / source_trace / numeric).',
    ].join('\n')
  );
}

export const WEBCITE_GUIDE_TOOL = {
  name: 'webcite_guide',
  description: `Call this free guide first to choose a Webcite workflow. Use workflow=source_trace to identify the original source of a screenshot or slide; use workflow=document_review to check every claim in an uploaded file. Costs 0 credits.`,
  inputSchema: {
    type: 'object' as const,
    properties: {
      workflow: {
        type: 'string',
        enum: ['quick_verify', 'document_quote', 'document_review', 'source_trace', 'numeric', 'choose'],
        description: 'Which workflow to explain. Default choose lists options.',
      },
      question: {
        type: 'string',
        description: 'Optional user question or claim to embed in examples',
      },
    },
  },
};
